/**
 * Currency table. Every amount in this library is an integer count of a
 * currency's minor unit, so the table is the one place that knows how many
 * decimals a currency has.
 */

const CURRENCIES = Object.freeze({
  // Two decimals.
  USD: { digits: 2, name: 'US dollar' },
  EUR: { digits: 2, name: 'Euro' },
  GBP: { digits: 2, name: 'Pound sterling' },
  CHF: { digits: 2, name: 'Swiss franc' },
  CAD: { digits: 2, name: 'Canadian dollar' },
  AUD: { digits: 2, name: 'Australian dollar' },
  SEK: { digits: 2, name: 'Swedish krona' },
  // No decimals.
  JPY: { digits: 0, name: 'Japanese yen' },
  KRW: { digits: 0, name: 'South Korean won' },
  VND: { digits: 0, name: 'Vietnamese dong' },
  CLP: { digits: 0, name: 'Chilean peso' },
  // Three decimals.
  KWD: { digits: 3, name: 'Kuwaiti dinar' },
  BHD: { digits: 3, name: 'Bahraini dinar' },
  OMR: { digits: 3, name: 'Omani rial' },
  JOD: { digits: 3, name: 'Jordanian dinar' },
  TND: { digits: 3, name: 'Tunisian dinar' },
});

/** All currency codes the library can bill in, sorted. */
export function supportedCurrencies() {
  return Object.keys(CURRENCIES).sort();
}

export function isSupportedCurrency(code) {
  return Object.hasOwn(CURRENCIES, code);
}

/** Throws unless `code` is a currency in the table. */
export function assertCurrency(code) {
  if (!isSupportedCurrency(code)) {
    throw new RangeError(`Unsupported currency: ${code}`);
  }
}

/** Number of decimals in a currency: JPY 0, USD 2, KWD 3. */
export function minorUnitDigits(code) {
  assertCurrency(code);
  return CURRENCIES[code].digits;
}

/** Minor units in one major unit: JPY 1, USD 100, KWD 1000. */
export function minorUnitsPerMajor(code) {
  return 10 ** minorUnitDigits(code);
}

export function currencyName(code) {
  assertCurrency(code);
  return CURRENCIES[code].name;
}
/**
 * Calendar helpers. Dates travel through the library as ISO strings
 * ("YYYY-MM-DD") with no time or zone attached; day arithmetic happens on UTC
 * day numbers so that daylight saving can never shift a result.
 */

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
const MS_PER_DAY = 86_400_000;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

/** Days in a month, where month is 1 to 12. */
export function daysInMonth(year, month) {
  if (month === 2) return isLeapYear(year) ? 29 : 28;
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

function pad(value, width) {
  return String(value).padStart(width, '0');
}

/** Splits an ISO date into numbers, rejecting impossible dates. */
export function parseIsoDate(text) {
  const match = ISO_DATE.exec(String(text));
  if (!match) throw new RangeError(`Not an ISO date: ${text}`);
  const [year, month, day] = match.slice(1).map(Number);
  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`Not a calendar date: ${text}`);
  }
  return { year, month, day };
}

export function formatIsoDate({ year, month, day }) {
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

function toDayNumber(text) {
  const { year, month, day } = parseIsoDate(text);
  return Date.UTC(year, month - 1, day) / MS_PER_DAY;
}

function fromDayNumber(dayNumber) {
  const date = new Date(dayNumber * MS_PER_DAY);
  return formatIsoDate({
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    day: date.getUTCDate(),
  });
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from, to) {
  return toDayNumber(to) - toDayNumber(from);
}

export function addDays(text, days) {
  return fromDayNumber(toDayNumber(text) + days);
}

/** Negative, zero or positive, like a sort comparator. */
export function compareDates(a, b) {
  return toDayNumber(a) - toDayNumber(b);
}

export function isLastDayOfMonth(text) {
  const { year, month, day } = parseIsoDate(text);
  return day === daysInMonth(year, month);
}

/**
 * Moves a date by whole calendar months. If the target month is too short the
 * result lands on its last day: addMonths("2023-01-31", 1) is "2023-02-28".
 */
export function addMonths(text, months) {
  const { year, month, day } = parseIsoDate(text);
  const monthIndex = year * 12 + (month - 1) + months;
  const targetYear = Math.floor(monthIndex / 12);
  const targetMonth = monthIndex - targetYear * 12 + 1;
  return formatIsoDate({
    year: targetYear,
    month: targetMonth,
    day: Math.min(day, daysInMonth(targetYear, targetMonth)),
  });
}

/** The calendar month of a date, as "YYYY-MM". */
export function monthKey(text) {
  return String(text).slice(0, 7);
}

/** The first day of the month after the given date. */
export function firstOfNextMonth(text) {
  const { year, month } = parseIsoDate(text);
  const next = addMonths(formatIsoDate({ year, month, day: 1 }), 1);
  return next;
}

/** "2024-02-29" becomes "29 Feb 2024", for statements. */
export function formatLongDate(text) {
  const { year, month, day } = parseIsoDate(text);
  return `${day} ${MONTHS[month - 1]} ${year}`;
}
/**
 * Conversions between integer minor units and the decimal text people read
 * and type, plus a few guarded integer helpers.
 */

import { assertCurrency } from './currencies.mjs';

const AMOUNT_PATTERN = /^(-)?(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d+))?$/;
const MINOR_PER_MAJOR = 100;
const DECIMALS = 2;

function groupThousands(digits) {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

/** Throws unless `value` is an integer count of minor units. */
export function assertMinorUnits(value, label = 'amount') {
  if (!Number.isSafeInteger(value)) {
    throw new TypeError(`${label} must be an integer number of minor units, got ${value}`);
  }
}

/**
 * Parses decimal text such as "1,234.50" into minor units. More decimals than
 * the currency has is an error, never a silent rounding.
 */
export function parseAmount(text, currency) {
  assertCurrency(currency);
  const match = AMOUNT_PATTERN.exec(String(text).trim());
  if (!match) throw new TypeError(`Not an amount: ${text}`);

  const [, sign, whole, fraction = ''] = match;
  if (fraction.length > DECIMALS) {
    throw new RangeError(`${text} has more decimals than ${currency} allows`);
  }
  const major = Number(whole.replaceAll(',', ''));
  const minor = Number(fraction.padEnd(DECIMALS, '0'));
  const amount = major * MINOR_PER_MAJOR + minor;
  assertMinorUnits(amount);
  return sign && amount !== 0 ? -amount : amount;
}

/** Decimal text without a currency code: "1,234.50", "-0.05". */
export function formatPlain(amount, currency) {
  assertCurrency(currency);
  assertMinorUnits(amount);
  const absolute = Math.abs(amount);
  const major = Math.floor(absolute / MINOR_PER_MAJOR);
  const minor = absolute % MINOR_PER_MAJOR;
  const sign = amount < 0 ? '-' : '';
  return `${sign}${groupThousands(String(major))}.${String(minor).padStart(DECIMALS, '0')}`;
}

/** Decimal text with the currency code in front: "USD 1,234.50". */
export function formatAmount(amount, currency) {
  return `${currency} ${formatPlain(amount, currency)}`;
}

/** Sums a list of minor-unit integers, checking each one. */
export function sumAmounts(amounts) {
  let total = 0;
  for (const amount of amounts) {
    assertMinorUnits(amount);
    total += amount;
  }
  assertMinorUnits(total, 'total');
  return total;
}
/**
 * Exact integer division with an explicit rounding mode.
 *
 * Everything goes through BigInt so that intermediate products (a price times
 * a tax rate, a line tax times a credited amount) cannot lose precision.
 */

export const ROUNDING_MODES = Object.freeze(['half-even', 'half-up', 'down']);
export const DEFAULT_ROUNDING_MODE = 'half-even';

function toBigInt(value, label) {
  if (typeof value === 'bigint') return value;
  if (!Number.isSafeInteger(value)) {
    throw new TypeError(`${label} must be a safe integer, got ${value}`);
  }
  return BigInt(value);
}

function roundQuotient(quotient, remainder, divisor, mode) {
  if (remainder === 0n || mode === 'down') return quotient;
  const twice = remainder * 2n;
  if (twice > divisor) return quotient + 1n;
  if (twice < divisor) return quotient;
  if (mode === 'half-up') return quotient + 1n;
  return quotient % 2n === 0n ? quotient : quotient + 1n;
}

/**
 * numerator / denominator, rounded to an integer. Rounding is sign symmetric:
 * divideRounded(-5, 2) is always -divideRounded(5, 2).
 */
export function divideRounded(numerator, denominator, mode = DEFAULT_ROUNDING_MODE) {
  if (!ROUNDING_MODES.includes(mode)) {
    throw new RangeError(`Unknown rounding mode: ${mode}`);
  }
  const n = toBigInt(numerator, 'numerator');
  const d = toBigInt(denominator, 'denominator');
  if (d === 0n) throw new RangeError('Cannot divide by zero');

  const negative = n < 0n !== d < 0n;
  const absN = n < 0n ? -n : n;
  const absD = d < 0n ? -d : d;
  const magnitude = roundQuotient(absN / absD, absN % absD, absD, mode);
  const result = Number(negative ? -magnitude : magnitude);
  if (!Number.isSafeInteger(result)) {
    throw new RangeError('Rounded result is too large to represent');
  }
  return result;
}

/** amount * numerator / denominator, rounded, without intermediate overflow. */
export function scaleRounded(amount, numerator, denominator, mode = DEFAULT_ROUNDING_MODE) {
  const product = toBigInt(amount, 'amount') * toBigInt(numerator, 'numerator');
  return divideRounded(product, denominator, mode);
}
/**
 * Document numbers. Tax rules require invoice and credit note numbers to run
 * without gaps, so a sequence only moves forward when a number is taken.
 */

import { assertPositiveInteger, assertText } from './validate.mjs';

const NUMBER_WIDTH = 4;

export function formatDocumentNumber(prefix, value) {
  return `${prefix}-${String(value).padStart(NUMBER_WIDTH, '0')}`;
}

export function createSequence(prefix, start = 1) {
  assertText(prefix, 'prefix');
  assertPositiveInteger(start, 'start');
  let next = start;
  return {
    peek() {
      return formatDocumentNumber(prefix, next);
    },
    take() {
      const number = formatDocumentNumber(prefix, next);
      next += 1;
      return number;
    },
  };
}
/** Small input checks and the error types shared across modules. */

export function assertText(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
}

export function assertPositiveInteger(value, label) {
  if (!Number.isInteger(value) || value < 1) {
    throw new RangeError(`${label} must be a positive integer, got ${value}`);
  }
}

export function assertNonNegativeInteger(value, label) {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(`${label} must be a non-negative integer, got ${value}`);
  }
}

/** Rates and percentages are integer basis points: 10000 is 100%. */
export function assertBasisPoints(value, label) {
  if (!Number.isInteger(value) || value < 0 || value > 10_000) {
    throw new RangeError(`${label} must be 0 to 10000 basis points, got ${value}`);
  }
}

export function assertNonEmptyArray(value, label) {
  if (!Array.isArray(value) || value.length === 0) {
    throw new RangeError(`${label} must have at least one entry`);
  }
}

/** A request that breaks a billing rule, such as crediting more than is left. */
export class BillingRuleError extends RangeError {
  constructor(message, details = {}) {
    super(message);
    this.name = 'BillingRuleError';
    this.details = details;
  }
}

/** A reference to a subscription, invoice or plan that does not exist. */
export class UnknownRecordError extends RangeError {
  constructor(kind, key) {
    super(`Unknown ${kind}: ${key}`);
    this.name = 'UnknownRecordError';
    this.kind = kind;
    this.key = key;
  }
}

