      if (!events.has(subscriptionId)) events.set(subscriptionId, []);
      events.get(subscriptionId).push(Object.freeze({ type, date, ...details }));
    },
    of(subscriptionId) {
      return [...(events.get(subscriptionId) ?? [])];
    },
  };
}

/** One readable line per event. */
export function describeEvents(events) {
  return events.map((event) => {
    const reference = event.invoiceNumber ? ` (${event.invoiceNumber})` : '';
    return `${event.date} ${event.type}${reference}`;
  });
}

/**
 * Splits an integer amount between lines in proportion to their weights, so
 * that the parts add up to the amount exactly.
 */

import { assertMinorUnits, sumAmounts } from '../core/money.mjs';

function assertWeights(weights) {
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('allocate needs at least one weight');
  }
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight < 0) {
      throw new RangeError(`Weights must be non-negative integers, got ${weight}`);
    }
  }
}

/**
 * allocate(amount, weights) returns one integer per weight. The amount may be
 * negative. At least one weight has to be positive.
 */
export function allocate(amount, weights) {
  assertMinorUnits(amount);
  assertWeights(weights);
  const totalWeight = sumAmounts(weights);
  if (totalWeight === 0) {
    throw new RangeError('allocate needs at least one positive weight');
  }

  const parts = weights.map((weight) => Math.round((amount * weight) / totalWeight));
  parts[parts.length - 1] += amount - sumAmounts(parts);
  return parts;
}
/**
 * Invoice-level discounts. A discount is either { percentBps } or { fixed }, and
 * applies only to lines with a positive amount: credit lines and free lines
 * never take any of it.
 */

import { assertMinorUnits, sumAmounts } from '../core/money.mjs';
import { scaleRounded } from '../core/rounding.mjs';
import { assertBasisPoints } from '../core/validate.mjs';
import { allocate } from './allocation.mjs';

const BASIS_POINTS = 10_000;

function resolveDiscount(discount, base) {
  if (discount == null) return 0;
  const hasPercent = discount.percentBps !== undefined;
  const hasFixed = discount.fixed !== undefined;
  if (hasPercent === hasFixed) {
    throw new TypeError('A discount needs exactly one of percentBps or fixed');
  }
  if (hasPercent) {
    assertBasisPoints(discount.percentBps, 'Discount');
    return scaleRounded(base, discount.percentBps, BASIS_POINTS);
  }
  assertMinorUnits(discount.fixed, 'discount');
  if (discount.fixed < 0 || discount.fixed > base) {
    throw new RangeError(`Discount of ${discount.fixed} does not fit a base of ${base}`);
  }
  return discount.fixed;
}

/** Adds `discount` and `net` to each line. */
export function applyDiscount(lines, discount) {
  const weights = lines.map((line) => Math.max(line.amount, 0));
  const discountTotal = resolveDiscount(discount, sumAmounts(weights));
  const shares = discountTotal === 0 ? lines.map(() => 0) : allocate(discountTotal, weights);
  return lines.map((line, position) => ({
    ...line,
    discount: shares[position],
    net: line.amount - shares[position],
  }));
}
/**
 * Invoices: turns priced lines into a discounted, taxed document whose numbers
 * are all integer minor units of a single currency.
 */

import { assertCurrency } from '../core/currencies.mjs';
import { parseIsoDate } from '../core/dates.mjs';
import { assertMinorUnits } from '../core/money.mjs';
import { assertBasisPoints, assertNonEmptyArray, assertPositiveInteger, assertText } from '../core/validate.mjs';
import { runPipeline } from './pipeline.mjs';

/**
 * A line is { description, unitAmount, quantity?, taxRateBps?, period?, reverses? }.
 *
 * `period` is the time the line pays for, { start, end }, end exclusive.
 * `reverses` marks a credit line as giving back part of an earlier charge, and
 * points at it: { invoiceNumber, lineIndex }.
 */
export function normalizeLine(input, position) {
  const {
    description,
    unitAmount,
    quantity = 1,
    taxRateBps = 0,
    period = null,
    reverses = null,
  } = input;
  assertText(description, `Line ${position} description`);
  assertMinorUnits(unitAmount, `Line ${position} unitAmount`);
  assertPositiveInteger(quantity, `Line ${position} quantity`);
  assertBasisPoints(taxRateBps, `Line ${position} tax rate`);
  const amount = unitAmount * quantity;
  assertMinorUnits(amount, `Line ${position} amount`);
  return { description, unitAmount, quantity, amount, taxRateBps, period, reverses };
}

/**
 * Builds an invoice.
 *
 * @param {object} input
 * @param {string} input.number invoice number
 * @param {string} input.customerId
 * @param {string} input.currency
 * @param {string} input.issueDate ISO date
 * @param {object[]} input.lines see normalizeLine
 * @param {object} [input.discount] { percentBps } or { fixed }
 * @param {number} [input.accountCredit] credit the customer holds on account
 * @param {string} [input.subscriptionId]
 */
export function buildInvoice(input) {
  const {
    number,
    customerId,
    currency,
    issueDate,
    lines,
    discount = null,
    accountCredit = 0,
    subscriptionId = null,
  } = input;
  assertCurrency(currency);
  parseIsoDate(issueDate);
  assertText(number, 'Invoice number');
  assertNonEmptyArray(lines, 'Invoice lines');
  assertMinorUnits(accountCredit, 'account credit');
  if (accountCredit < 0) throw new RangeError('Account credit cannot be negative');

  const finished = runPipeline({
    lines: lines.map(normalizeLine),
    discount,
    accountCredit,
  });

  return {
    number,
    customerId,
    subscriptionId,
    currency,
    issueDate,
    lines: finished.lines,
    taxSummary: finished.taxSummary,
    subtotal: finished.subtotal,
    discountTotal: finished.discountTotal,
    netTotal: finished.netTotal,
    taxTotal: finished.taxTotal,
    total: finished.total,
    creditApplied: finished.creditApplied,
    amountDue: finished.amountDue,
  };
}
/**
 * The steps that turn priced lines into a finished invoice. Each step takes the
 * draft and returns a new one, and later steps rely on what earlier ones added.
 */

import { sumAmounts } from '../core/money.mjs';
import { applyTax, taxSummary } from '../tax/calculate.mjs';
import { allocate } from './allocation.mjs';
import { applyDiscount } from './discounts.mjs';

export function computeTotals(lines, summary) {
  const subtotal = sumAmounts(lines.map((line) => line.amount));
  const discountTotal = sumAmounts(lines.map((line) => line.discount));
  const netTotal = sumAmounts(lines.map((line) => line.net));
  const taxTotal = sumAmounts(summary.map((row) => row.tax));
  return { subtotal, discountTotal, netTotal, taxTotal, total: netTotal + taxTotal };
}

export function applyAccountCredit(draft) {
  const weights = draft.lines.map((line) => Math.max(line.net, 0));
  const creditApplied = Math.min(draft.accountCredit, sumAmounts(weights));
  if (creditApplied === 0) return { ...draft, creditApplied };
  const shares = allocate(creditApplied, weights);
  return {
    ...draft,
    creditApplied,
    lines: draft.lines.map((line, position) => ({ ...line, net: line.net - shares[position] })),
  };
}

function discountStage(draft) {
  return { ...draft, lines: applyDiscount(draft.lines, draft.discount) };
}

function taxStage(draft) {
  const lines = applyTax(draft.lines);
  return { ...draft, lines, taxSummary: taxSummary(lines) };
}

function totalsStage(draft) {
  const totals = computeTotals(draft.lines, draft.taxSummary);
  return { ...draft, ...totals, amountDue: Math.max(totals.total, 0) };
}

const STAGES = [discountStage, applyAccountCredit, taxStage, totalsStage];

export function runPipeline(draft) {
  return STAGES.reduce((current, stage) => stage(current), draft);
}
/** Tax on amounts and on invoice lines. Rates are integer basis points. */

import { assertMinorUnits } from '../core/money.mjs';
import { scaleRounded } from '../core/rounding.mjs';
import { assertBasisPoints } from '../core/validate.mjs';

export function groupByRate(lines) {
  const groups = new Map();
  lines.forEach((line, position) => {
    assertBasisPoints(line.taxRateBps, 'Tax rate');
    if (!groups.has(line.taxRateBps)) groups.set(line.taxRateBps, []);
    groups.get(line.taxRateBps).push({ line, position });
  });
  return groups;
}

export function taxableAmount(members) {
  return members.reduce((total, { line }) => total + line.net, 0);
}

const BASIS_POINTS = 10_000;

/** Tax on a net amount at a rate. */
export function taxForAmount(net, rateBps) {
  assertMinorUnits(net);
  assertBasisPoints(rateBps, 'Tax rate');
  return scaleRounded(net, rateBps, BASIS_POINTS);
}

/** Adds `tax` and `gross` to each discounted line. */
export function applyTax(lines) {
  return lines.map((line) => {
    const tax = taxForAmount(line.net, line.taxRateBps);
    return { ...line, tax, gross: line.net + tax };
  });
}

/** One row per rate: the taxable amount and the tax due on it. */
export function taxSummary(lines) {
  const rows = [];
  for (const [rateBps, members] of groupByRate(lines)) {
    const taxable = taxableAmount(members);
    rows.push({ rateBps, taxable, tax: taxForAmount(taxable, rateBps) });
  }
  return rows;
}
/**
 * Tax tables. A region's rate can change over time, so each region holds a list
 * of rates with the date each one starts applying. The rate on a charge is the
 * one in force on the day it is invoiced.
 */

import { compareDates, parseIsoDate } from '../core/dates.mjs';
import { UnknownRecordError, assertBasisPoints, assertNonEmptyArray } from '../core/validate.mjs';

function normalizeHistory(region, history) {
  assertNonEmptyArray(history, `Tax history for ${region}`);
  const entries = history.map(({ from, rateBps }) => {
    parseIsoDate(from);
    assertBasisPoints(rateBps, `Tax rate for ${region}`);
    return Object.freeze({ from, rateBps });
  });
  entries.sort((a, b) => compareDates(a.from, b.from));
  return Object.freeze(entries);
}

/**
 * defineTaxTable({
 *   NL: [{ from: '2000-01-01', rateBps: 2100 }],
 *   SE: [{ from: '2000-01-01', rateBps: 2500 }, { from: '2025-07-01', rateBps: 2200 }],
 * })
 */
export function defineTaxTable(regions) {
  const table = new Map();
  for (const [region, history] of Object.entries(regions)) {
    table.set(region, normalizeHistory(region, history));
  }
  return Object.freeze({
    regions: () => [...table.keys()],
    historyOf(region) {
      const history = table.get(region);
      if (!history) throw new UnknownRecordError('tax region', region);
      return history;
    },
  });
}

/** The rate in force in a region on a date. */
export function rateOn(table, region, date) {
  parseIsoDate(date);
  let current = null;
  for (const entry of table.historyOf(region)) {
    if (compareDates(entry.from, date) <= 0) current = entry;
  }
  if (!current) throw new RangeError(`No tax rate for ${region} on ${date}`);
  return current.rateBps;
}

/** The rate changes in a region that take effect between two dates, inclusive. */
export function rateChangesBetween(table, region, from, to) {
  parseIsoDate(from);
  parseIsoDate(to);
  return table
    .historyOf(region)
    .filter((entry) => compareDates(entry.from, from) >= 0 && compareDates(entry.from, to) <= 0);
}
/**
 * Customer account credit: money we owe a customer that has not gone back to
 * them yet. Held per customer and per currency, as a list of dated entries.
 */

import { assertMinorUnits, sumAmounts } from '../core/money.mjs';

function keyOf(customerId, currency) {
  return `${customerId}|${currency}`;
}

export function createAccountLedger() {
  const entries = new Map();

  function listFor(customerId, currency) {
    return entries.get(keyOf(customerId, currency)) ?? [];
  }

  function append(customerId, currency, entry) {
    const key = keyOf(customerId, currency);
    if (!entries.has(key)) entries.set(key, []);
    entries.get(key).push(Object.freeze(entry));
  }

  function balance(customerId, currency) {
    return sumAmounts(listFor(customerId, currency).map((entry) => entry.amount));
  }

  return {
    balance,
    entries: (customerId, currency) => [...listFor(customerId, currency)],
    add(customerId, currency, amount, details) {
      assertMinorUnits(amount, 'account credit');
      if (amount <= 0) throw new RangeError('Account credit must be added in positive amounts');
      append(customerId, currency, { amount, ...details });
    },
    take(customerId, currency, amount, details) {
      assertMinorUnits(amount, 'account credit');
      if (amount <= 0) throw new RangeError('Account credit must be taken in positive amounts');
      if (amount > balance(customerId, currency)) {
        throw new RangeError(`Customer ${customerId} does not hold ${amount} in ${currency}`);
      }
      append(customerId, currency, { amount: -amount, ...details });
    },
  };
}
/**
 * What is still owed on an invoice. Payments and write-offs both reduce it, but
 * only payments are cash we hold.
 */

import { parseIsoDate } from '../core/dates.mjs';
import { assertMinorUnits, sumAmounts } from '../core/money.mjs';

export const SETTLEMENT_KINDS = Object.freeze(['payment', 'write-off']);

export function createSettlement(invoice, kind, amount, date) {
  if (!SETTLEMENT_KINDS.includes(kind)) throw new RangeError(`Unknown settlement kind: ${kind}`);
  assertMinorUnits(amount, 'settlement');
  parseIsoDate(date);
  if (amount <= 0) throw new RangeError('A settlement must be a positive amount');
  return Object.freeze({
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    currency: invoice.currency,
    kind,
    amount,
    date,
  });
}

/** Everything that has reduced the invoice's open amount this way. */
export function settledTotal(settlements) {
  return sumAmounts(settlements.map((settlement) => settlement.amount));
}

/** The cash received, leaving out write-offs. */
export function cashReceived(settlements) {
  return settledTotal(settlements.filter((settlement) => settlement.kind === 'payment'));
}

function creditedAgainstBalance(notes) {
  return sumAmounts(
    notes.map((note) => (note.settlement ? note.settlement.againstBalance : note.total)),
  );
}

/**
 * The amount still owed after credit notes and payments. A note carrying a
 * settlement says how much of it went against the balance. A note issued on its
 * own counts in full.
 */
export function invoiceBalance(invoice, notes = [], settlements = []) {
  return Math.max(invoice.total, 0) - creditedAgainstBalance(notes) - settledTotal(settlements);
}
/**
 * Credit notes reverse part or all of an invoice's lines. An invoice can have
 * any number of them, so each new note is issued against the ones before it.
 *
 * Credit lines on later invoices can also give back part of an earlier charge.
 * Those are read here in the same shape as credit note lines.
 */

import { compareDates, parseIsoDate } from '../core/dates.mjs';
import { assertMinorUnits, parseAmount, sumAmounts } from '../core/money.mjs';
import { assertNonEmptyArray, assertText } from '../core/validate.mjs';
import { taxForAmount } from '../tax/calculate.mjs';

/** One entry per earlier invoice a new invoice gives money back on. */
export function reversalsFromInvoice(invoice) {
  const byOrigin = new Map();
  for (const line of invoice.lines) {
    if (!line.reverses) continue;
    const { invoiceNumber, lineIndex } = line.reverses;
    if (!byOrigin.has(invoiceNumber)) byOrigin.set(invoiceNumber, []);
    byOrigin.get(invoiceNumber).push({ lineIndex, net: -line.net, tax: -line.tax });
  }
  return [...byOrigin].map(([invoiceNumber, lines]) => ({
    kind: 'reversal',
    number: invoice.number,
    invoiceNumber,
    currency: invoice.currency,
    date: invoice.issueDate,
    lines,
  }));
}

function assertNotesBelongTo(invoice, notes) {
  for (const note of notes) {
    if (note.invoiceNumber !== invoice.number) {
      throw new RangeError(`Credit note ${note.number} belongs to invoice ${note.invoiceNumber}`);
    }
  }
}

/** Per invoice line, the net and tax already given back. */
export function creditedToDate(invoice, notes = []) {
  assertNotesBelongTo(invoice, notes);
  const credited = invoice.lines.map(() => ({ net: 0, tax: 0 }));
  for (const note of notes) {
    for (const line of note.lines) {
      credited[line.lineIndex].net += line.net;
      credited[line.lineIndex].tax += line.tax;
    }
  }
  return credited;
}

/** Per invoice line, the net amount that can still be credited. */
export function remainingCreditable(invoice, notes = []) {
  const credited = creditedToDate(invoice, notes);
  return invoice.lines.map((line, index) => Math.max(line.amount - credited[index].net, 0));
}

function requestedAmount(invoice, request, available) {
  if (request.amount !== undefined) {
    assertMinorUnits(request.amount, 'credit amount');
    return request.amount;
  }
  if (request.amountText !== undefined) return parseAmount(request.amountText, invoice.currency);
  return available;
}

function creditLine(invoice, entry, credited) {
  const line = invoice.lines[entry.lineIndex];
  if (!line) throw new RangeError(`Invoice ${invoice.number} has no line ${entry.lineIndex}`);
  if (line.net <= 0) {
    throw new RangeError(`Line ${entry.lineIndex} of ${invoice.number} has nothing to credit`);
  }

  const soFar = credited[entry.lineIndex];
  const available = Math.max(line.amount - soFar.net, 0);
  const amount = requestedAmount(invoice, entry, available);
  if (amount <= 0 || amount > line.amount) {
    throw new RangeError(`Cannot credit ${amount} on line ${entry.lineIndex} of ${invoice.number}`);
  }

  const tax = taxForAmount(amount, line.taxRateBps);
  credited[entry.lineIndex] = { net: soFar.net + amount, tax: soFar.tax + tax };
  return {
    lineIndex: entry.lineIndex,
    description: line.description,
    taxRateBps: line.taxRateBps,
    net: amount,
    tax,
    gross: amount + tax,
  };
}

/**
 * Issues a credit note. `request.lines` holds { lineIndex, amount } entries;
 * amount is a net amount in minor units, or decimal text as amountText. With
 * neither, the entry credits everything left on that line.
 */
export function issueCreditNote(invoice, request, priorNotes = []) {
  const { number, date, reason = '', lines } = request;
  assertText(number, 'Credit note number');
  parseIsoDate(date);
  if (compareDates(date, invoice.issueDate) < 0) {
    throw new RangeError(`Credit note ${number} predates invoice ${invoice.number}`);
  }
  assertNonEmptyArray(lines, 'Credit note lines');

  const credited = creditedToDate(invoice, priorNotes);
  const noteLines = lines.map((entry) => creditLine(invoice, entry, credited));

  const netTotal = sumAmounts(noteLines.map((line) => line.net));
  const taxTotal = sumAmounts(noteLines.map((line) => line.tax));
  return {
    number,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    currency: invoice.currency,
    date,
    reason,
    lines: noteLines,
    netTotal,
    taxTotal,
    total: netTotal + taxTotal,
  };
}

/** Credits everything still creditable on an invoice's positive lines. */
export function creditInvoiceInFull(invoice, request, priorNotes = []) {
  const available = remainingCreditable(invoice, priorNotes);
  const lines = invoice.lines
    .map((line, lineIndex) => ({ line, lineIndex }))
    .filter(({ line, lineIndex }) => line.net > 0 && available[lineIndex] > 0)
    .map(({ lineIndex }) => ({ lineIndex }));
  return issueCreditNote(invoice, { ...request, lines }, priorNotes);
}
/**
 * Overdue invoices. Invoices fall due a fixed number of days after they are
 * issued, an open invoice moves through reminder stages as it gets older, and the
 * aging report sorts open balances by how overdue they are.
 */

import { addDays, compareDates, daysBetween } from '../core/dates.mjs';

export const DEFAULT_TERMS_DAYS = 30;

const STAGES = Object.freeze([
  { name: 'final-notice', after: 60 },
  { name: 'second-reminder', after: 30 },
  { name: 'first-reminder', after: 7 },
  { name: 'overdue', after: 0 },
]);

export function dueDate(invoice, termsDays = DEFAULT_TERMS_DAYS) {
  return addDays(invoice.issueDate, termsDays);
}

export function daysOverdue(invoice, asOf, termsDays = DEFAULT_TERMS_DAYS) {
  return daysBetween(dueDate(invoice, termsDays), asOf);
}

/** The reminder stage an invoice has reached, or null if it is not overdue. */
export function reminderStage(invoice, asOf, termsDays = DEFAULT_TERMS_DAYS) {
  if (compareDates(asOf, dueDate(invoice, termsDays)) <= 0) return null;
  const overdue = daysOverdue(invoice, asOf, termsDays);
  return STAGES.find((stage) => overdue > stage.after)?.name ?? null;
}

/**
 * Open invoices that need a reminder, oldest first.
 *
 * @param {object[]} invoices
 * @param {(invoice: object) => number} balanceOf
 * @param {string} asOf
 */
export function dunningQueue(invoices, balanceOf, asOf, termsDays = DEFAULT_TERMS_DAYS) {
  return invoices
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      currency: invoice.currency,
      balance: balanceOf(invoice),
      stage: reminderStage(invoice, asOf, termsDays),
      overdueDays: daysOverdue(invoice, asOf, termsDays),
    }))
    .filter((entry) => entry.balance > 0 && entry.stage !== null)
    .sort((a, b) => b.overdueDays - a.overdueDays || a.number.localeCompare(b.number));
}

const BUCKETS = Object.freeze([
  { name: 'current', upTo: 0 },
  { name: '1-30', upTo: 30 },
  { name: '31-60', upTo: 60 },
  { name: '61+', upTo: Infinity },
]);

function bucketFor(overdue) {
  return BUCKETS.find((bucket) => overdue <= bucket.upTo).name;
}

export function agingReport({ invoices, balanceOf, asOf, currency, termsDays = DEFAULT_TERMS_DAYS }) {
  const report = Object.fromEntries(BUCKETS.map((bucket) => [bucket.name, 0]));
  for (const invoice of invoices) {
    if (invoice.currency !== currency) continue;
    const balance = balanceOf(invoice);
    if (balance <= 0) continue;
    report[bucketFor(daysOverdue(invoice, asOf, termsDays))] += balance;
  }
  return report;
}

/** The totals behind a dunning queue, per currency and stage, for the team lead. */
export function dunningSummary(queue) {
  const summary = {};
  for (const { currency, stage, balance } of queue) {
    summary[currency] ??= {};
    summary[currency][stage] = (summary[currency][stage] ?? 0) + balance;
  }
  return summary;
}
/**
 * Instalment plans: an agreement to pay an open balance in equal parts on set
 * dates, for customers who ask for more time.
 */

import { addMonths, compareDates, parseIsoDate } from '../core/dates.mjs';
import { assertMinorUnits } from '../core/money.mjs';
import { assertPositiveInteger } from '../core/validate.mjs';
import { allocate } from '../invoicing/allocation.mjs';

/**
 * Splits a balance into `count` monthly instalments from `firstDue`.
 *
 * @returns {{number: number, due: string, amount: number}[]}
 */
export function planInstalments(balance, count, firstDue) {
  assertMinorUnits(balance, 'balance');
  if (balance <= 0) throw new RangeError('There is nothing to spread over instalments');
  assertPositiveInteger(count, 'Instalment count');
  parseIsoDate(firstDue);
  const amounts = allocate(balance, new Array(count).fill(1));
  return amounts.map((amount, position) => ({
    number: position + 1,
    due: addMonths(firstDue, position),
    amount,
  }));
}

/**
 * Applies what has been paid to the plan, oldest instalment first, and reports
 * where each one stands on a date.
 */
export function instalmentStatus(plan, paid, asOf) {
  assertMinorUnits(paid, 'paid');
  parseIsoDate(asOf);
  let remaining = paid;
  return plan.map((instalment) => {
    const covered = Math.min(remaining, instalment.amount);
    remaining -= covered;
    const open = instalment.amount - covered;
    let state = 'paid';
    if (open > 0) state = compareDates(asOf, instalment.due) > 0 ? 'late' : 'upcoming';
    return { ...instalment, covered, open, state };
  });
}

/** The amount that should have been paid by a date. */
export function amountDueBy(plan, asOf) {
  parseIsoDate(asOf);
  return plan
    .filter((instalment) => compareDates(instalment.due, asOf) <= 0)
    .reduce((total, instalment) => total + instalment.amount, 0);
}
/**
 * Double-entry journal for the accounting system. Every document becomes one
 * entry, and each leg is signed: positive is a debit, negative a credit. An entry
 * whose legs do not sum to zero is rejected by the accounting system on import.
 */

import { sumAmounts } from '../core/money.mjs';

export const ACCOUNTS = Object.freeze({
  receivables: '1100 Receivables',
  cash: '1000 Cash',
  customerCredit: '2100 Customer credit',
  taxPayable: '2200 Tax payable',
  revenue: '4000 Revenue',
  badDebt: '6900 Bad debt',
});

function leg(account, amount) {
  return { account, amount };
}

function entry(date, reference, currency, legs) {
  return {
    date,
    reference,
    currency,
    legs: legs.filter(({ amount }) => amount !== 0),
  };
}

/** The entry for an invoice. */
export function invoiceEntry(invoice) {
  const toAccount = Math.max(-invoice.total, 0);
  return entry(invoice.issueDate, invoice.number, invoice.currency, [
    leg(ACCOUNTS.receivables, invoice.amountDue),
    leg(ACCOUNTS.customerCredit, invoice.creditApplied - toAccount),
    leg(ACCOUNTS.revenue, -invoice.netTotal),
    leg(ACCOUNTS.taxPayable, -invoice.taxTotal),
  ]);
}

/** The entry for a credit note, following where its money went. */
export function creditNoteEntry(note) {
  const settlement = note.settlement ?? { againstBalance: note.total, refunded: 0, toAccount: 0 };
  return entry(note.date, note.number, note.currency, [
    leg(ACCOUNTS.revenue, note.netTotal),
    leg(ACCOUNTS.taxPayable, note.taxTotal),
    leg(ACCOUNTS.receivables, -settlement.againstBalance),
    leg(ACCOUNTS.cash, -settlement.refunded),
    leg(ACCOUNTS.customerCredit, -settlement.toAccount),
  ]);
}

/** The entry for a payment or a write-off. */
export function settlementEntry(settlement) {
  const offset = settlement.kind === 'payment' ? ACCOUNTS.cash : ACCOUNTS.badDebt;
  return entry(settlement.date, settlement.invoiceNumber, settlement.currency, [
    leg(offset, settlement.amount),
    leg(ACCOUNTS.receivables, -settlement.amount),
  ]);
}

export function entryImbalance(journalEntry) {
  return sumAmounts(journalEntry.legs.map(({ amount }) => amount));
}

/** All entries for a set of documents, in date order. */
export function buildJournal({ invoices, notes, settlements }) {
  const entries = [
    ...invoices.map(invoiceEntry),
    ...notes.map(creditNoteEntry),
    ...settlements.map(settlementEntry),
  ];
  return entries.sort((a, b) => a.date.localeCompare(b.date) || a.reference.localeCompare(b.reference));
}

/** Per account and currency, the balance the journal leaves. */
export function trialBalance(entries) {
  const balances = new Map();
  for (const { currency, legs } of entries) {
    for (const { account, amount } of legs) {
      const key = `${currency} ${account}`;
      balances.set(key, (balances.get(key) ?? 0) + amount);
    }
  }
  return Object.fromEntries([...balances].sort(([a], [b]) => a.localeCompare(b)));
}
/** Where the money on a credit note ends up. */

/**
 * Splits a credit note's total between the invoice's open balance, a refund and
 * the customer's account.
 *
 * @param {number} noteTotal
 * @param {object} position
 * @param {number} position.openBalance what is still owed on the invoice
 */
export function settleCreditNote(noteTotal, { openBalance }) {
  const againstBalance = Math.min(noteTotal, Math.max(openBalance, 0));
  const refunded = noteTotal - againstBalance;
  const toAccount = 0;
  return Object.freeze({ againstBalance, refunded, toAccount });
}

/** Refunds that still have to be paid out, oldest first. */
export function refundQueue(notes, paidOut = []) {
  const done = new Set(paidOut);
  return notes
    .filter((note) => (note.settlement?.refunded ?? 0) > 0 && !done.has(note.number))
    .map((note) => ({
      noteNumber: note.number,
      invoiceNumber: note.invoiceNumber,
      customerId: note.customerId,
      currency: note.currency,
      amount: note.settlement.refunded,
      date: note.date,
    }))
    .sort((a, b) => a.date.localeCompare(b.date) || a.noteNumber.localeCompare(b.noteNumber));
}

/**
 * The book of business: one place that holds subscriptions, invoices, credit
 * notes, payments and account credit, and keeps them consistent as operations
 * happen one after another.
 */

import { compareDates } from './core/dates.mjs';
import { createCustomerRegistry, isReverseCharge } from './customers/registry.mjs';
import { UnknownRecordError } from './core/validate.mjs';
import { createSequence } from './core/sequence.mjs';
import { buildInvoice } from './invoicing/invoice.mjs';
import { createAccountLedger } from './ledger/account.mjs';
import { createSettlement, invoiceBalance } from './ledger/balances.mjs';
import {
  creditInvoiceInFull,
  creditedToDate,
  issueCreditNote,
  remainingCreditable,
} from './ledger/credit-notes.mjs';
import { agingReport, dunningQueue } from './ledger/dunning.mjs';
import { buildJournal, entryImbalance, trialBalance } from './ledger/journal.mjs';
import { refundQueue, settleCreditNote } from './ledger/settlement.mjs';
import { bookSnapshot, creditNotesCsv, invoicesCsv, journalCsv, revenueCsv } from './reporting/export.mjs';
import { customerSummary, renderAccountStatement } from './reporting/customer.mjs';
import {
  monthlyChurnBps,
  monthlyRecurringRevenue,
  renewalForecast,
  subscriberMovement,
  subscribersByPlan,
} from './reporting/forecast.mjs';
import { deferredRevenue, revenueByMonth } from './reporting/revenue.mjs';
import { renderStatement } from './reporting/statement.mjs';
import { taxReport } from './reporting/tax-report.mjs';
import { applyPlanChange, draftCancellation, draftPlanChange, endRecord } from './subscriptions/plan-change.mjs';
import { createRecord } from './subscriptions/record.mjs';
import { draftPeriodInvoice, enterPeriod, firstPeriod, nextPeriod } from './subscriptions/renewal.mjs';
import {
  applyScheduled,
  clearScheduled,
  isCancelling,
  scheduleChange,
} from './subscriptions/scheduled-changes.mjs';
import { createTimeline, describeEvents } from './subscriptions/timeline.mjs';
import { rateOn } from './tax/rates.mjs';

/**
 * @param {object} options
 * @param {object} options.catalog from createCatalog
 * @param {object} [options.taxTable] from defineTaxTable; without one, nothing is taxed
 * @param {string} [options.sellerRegion] where the seller is registered, for reverse charge
 */
export function createBook({ catalog, taxTable = null, sellerRegion = null }) {
  const subscriptions = new Map();
  const invoices = new Map();
  const notes = [];
  const settlements = [];
  const account = createAccountLedger();
  const customers = createCustomerRegistry();
  const refundsPaidOut = [];
  const timeline = createTimeline();
  const invoiceNumbers = createSequence('INV');
  const noteNumbers = createSequence('CN');

  function requireSubscription(id) {
    const record = subscriptions.get(id);
    if (!record) throw new UnknownRecordError('subscription', id);
    return record;
  }

  function requireInvoice(number) {
    const invoice = invoices.get(number);
    if (!invoice) throw new UnknownRecordError('invoice', number);
    return invoice;
  }

  function taxRate(record, date) {
    if (!record.region || !taxTable) return 0;
    if (isReverseCharge(customers.find(record.customerId), record.region, sellerRegion)) return 0;
    return rateOn(taxTable, record.region, date);
  }

  function notesOn(number) {
    return notes.filter((note) => note.invoiceNumber === number);
  }

  function settlementsOn(number) {
    return settlements.filter((settlement) => settlement.invoiceNumber === number);
  }

  /** Everything already given back on an invoice's lines. */
  function drawnAgainst(number) {
    return notesOn(number);
  }

  function balanceOf(invoice) {
    return invoiceBalance(invoice, notesOn(invoice.number), settlementsOn(invoice.number));
  }

  function reversedNetOnSegment(segment) {
    const origin = requireInvoice(segment.invoiceNumber);
    return creditedToDate(origin, drawnAgainst(segment.invoiceNumber))[segment.lineIndex].net;
  }

  /** Finishes an invoice and moves account credit as it says. */
  function issue(input) {
    const { customerId, currency } = input;
    const invoice = buildInvoice({ ...input, accountCredit: account.balance(customerId, currency) });
    invoices.set(invoice.number, invoice);
    const details = { date: invoice.issueDate, reference: invoice.number };
    if (invoice.creditApplied > 0) account.take(customerId, currency, invoice.creditApplied, details);
    if (invoice.total < 0) account.add(customerId, currency, -invoice.total, details);
    return invoice;
  }

  function subscribe(request) {
    const { planCode, couponCode, discount, ...rest } = request;
    if (subscriptions.has(rest.id)) throw new RangeError(`Subscription ${rest.id} already exists`);
    const coupon = couponCode ? catalog.coupon(couponCode) : null;
    const record = createRecord({ ...rest, plan: catalog.plan(planCode), coupon });
    const period = firstPeriod(record);
    const invoice = issue(
      draftPeriodInvoice(record, period, {
        number: invoiceNumbers.take(),
        taxRateBps: taxRate(record, period.start),
        discount,
      }),
    );
    subscriptions.set(record.id, enterPeriod(record, period, invoice));
    timeline.record(record.id, 'subscribed', period.start, { invoiceNumber: invoice.number });
    return invoice;
  }

  /**
   * Moves a subscription into its next period. Returns the renewal invoice, or
   * null if the subscription was set to end instead.
   */
  function renew(id, options = {}) {
    const record = requireSubscription(id);
    if (record.status !== 'active') throw new RangeError(`Subscription ${id} has ended`);
    const period = nextPeriod(record);
    if (isCancelling(record)) {
      subscriptions.set(id, endRecord(record, period.start));
      timeline.record(id, 'ended', period.start);
      return null;
    }
    const terms = applyScheduled(record);
    const invoice = issue(
      draftPeriodInvoice(terms, period, {
        number: invoiceNumbers.take(),
        taxRateBps: taxRate(terms, period.start),
        discount: options.discount,
      }),
    );
    subscriptions.set(id, enterPeriod(terms, period, invoice));
    timeline.record(id, 'renewed', period.start, { invoiceNumber: invoice.number });
    return invoice;
  }

  function resolveChange(request) {
    const { date, planCode, seats } = request;
    return { date, seats, plan: planCode ? catalog.plan(planCode) : undefined };
  }

  /** Changes plan or seats today. Returns the invoice for the change. */
  function changePlan(id, request) {
    const record = requireSubscription(id);
    const change = resolveChange(request);
    const invoice = issue(
      draftPlanChange(record, change, {
        number: invoiceNumbers.take(),
        taxRateBps: taxRate(record, change.date),
        reversedNet: reversedNetOnSegment(record.segment),
      }),
    );
    subscriptions.set(id, applyPlanChange(record, change, invoice));
    timeline.record(id, 'changed', change.date, { invoiceNumber: invoice.number });
    return invoice;
  }

  /** What a change would come to, without doing it. */
  function previewChange(id, request) {
    const record = requireSubscription(id);
    const change = resolveChange(request);
    return buildInvoice({
      ...draftPlanChange(record, change, {
        number: 'PREVIEW',
        taxRateBps: taxRate(record, change.date),
        reversedNet: reversedNetOnSegment(record.segment),
      }),
      accountCredit: account.balance(record.customerId, record.currency),
    });
  }

  /** Sets new terms to take effect at the next renewal. */
  function scheduleForRenewal(id, request) {
    const record = requireSubscription(id);
    const { planCode, seats } = request;
    const plan = planCode ? catalog.plan(planCode) : undefined;
    subscriptions.set(id, scheduleChange(record, { plan, seats }));
    timeline.record(id, 'change-scheduled', record.period.start);
  }

  function clearSchedule(id) {
    const record = requireSubscription(id);
    subscriptions.set(id, clearScheduled(record));
    timeline.record(id, 'schedule-cleared', record.period.start);
  }

  /**
   * Cancels a subscription, either straight away (mode 'immediate'), giving back
   * the unused time, or when the current period ends (mode 'period-end').
   * Returns the invoice for the unused time, if there is one.
   */
  function cancel(id, { date, mode = 'immediate' }) {
    const record = requireSubscription(id);
    if (record.status !== 'active') throw new RangeError(`Subscription ${id} has ended`);
    if (mode === 'period-end') {
      subscriptions.set(id, scheduleChange(record, { cancel: true }));
      timeline.record(id, 'cancelled', date);
      return null;
    }
    if (mode !== 'immediate') throw new RangeError(`Unknown cancellation mode: ${mode}`);

    const input = draftCancellation(record, date, {
      number: invoiceNumbers.peek(),
      taxRateBps: taxRate(record, date),
      reversedNet: reversedNetOnSegment(record.segment),
    });
    const invoice = input ? issue({ ...input, number: invoiceNumbers.take() }) : null;
    subscriptions.set(id, endRecord(record, date));
    timeline.record(id, 'cancelled', date, invoice ? { invoiceNumber: invoice.number } : {});
    return invoice;
  }

  /**
   * Issues a credit note. Pass `lines` to credit part of an invoice, or leave it
   * out to credit everything still creditable.
   */
  function creditInvoice(number, request) {
    const invoice = requireInvoice(number);
    const { date, reason, lines } = request;
    const prior = drawnAgainst(number);
    const noteRequest = { number: noteNumbers.peek(), date, reason, lines };
    const draft = lines
      ? issueCreditNote(invoice, noteRequest, prior)
      : creditInvoiceInFull(invoice, noteRequest, prior);
    noteNumbers.take();

    const settlement = settleCreditNote(draft.total, {
      openBalance: balanceOf(invoice),
    });
    const note = { ...draft, settlement };
    notes.push(note);
    if (settlement.toAccount > 0) {
      account.add(invoice.customerId, invoice.currency, settlement.toAccount, {
        date,
        reference: note.number,
      });
    }
    return note;
  }

  /** Puts goodwill credit on a customer's account. */
  function grantAccountCredit(customerId, currency, { amount, date, reason = 'goodwill' }) {
    account.add(customerId, currency, amount, { date, reference: reason });
  }

  function settle(number, kind, { amount, date }) {
    const invoice = requireInvoice(number);
    const settlement = createSettlement(invoice, kind, amount, date);
    if (compareDates(date, invoice.issueDate) < 0) {
      throw new RangeError(`${kind} on ${number} predates the invoice`);
    }
    if (amount > balanceOf(invoice)) {
      throw new RangeError(`${number} has less than ${amount} open`);
    }
    settlements.push(settlement);
    return settlement;
  }

  /**
   * Renews every active subscription whose current period has ended by `asOf`,
   * as many times as it takes to catch up. Returns the invoices in order.
   */
  function runRenewals(asOf) {
    const issued = [];
    for (const id of subscriptions.keys()) {
      let record = subscriptions.get(id);
      while (record.status === 'active' && compareDates(record.period.end, asOf) <= 0) {
        const invoice = renew(id);
        if (invoice) issued.push(invoice);
        record = subscriptions.get(id);
      }
    }
    return issued;
  }

  function allInvoices() {
    return [...invoices.values()];
  }

  function journal() {
    return buildJournal({ invoices: allInvoices(), notes, settlements });
  }

  return {
    customers,
    subscribe,
    renew,
    runRenewals,
    changePlan,
    previewChange,
    scheduleForRenewal,
    clearSchedule,
    cancel,
    creditInvoice,
    grantAccountCredit,
    pay: (number, payment) => settle(number, 'payment', payment),
    writeOff: (number, entry) => settle(number, 'write-off', entry),

    subscription: requireSubscription,
    invoice: requireInvoice,
    invoices: allInvoices,
    notes: () => [...notes],
    notesOn,
    settlementsOn,
    balanceOf: (number) => balanceOf(requireInvoice(number)),
    remainingCreditable: (number) => remainingCreditable(requireInvoice(number), drawnAgainst(number)),
    accountCredit: (customerId, currency) => account.balance(customerId, currency),
    timeline: (id) => describeEvents(timeline.of(id)),

    statement(number) {
      return renderStatement(requireInvoice(number), notesOn(number), settlementsOn(number));
    },
    accountStatement(customerId, currency) {
      return renderAccountStatement(customerId, currency, account.entries(customerId, currency));
    },
    revenueByMonth: (currency) => revenueByMonth({ invoices: allInvoices(), notes, currency }),
    taxReport: (currency, month) => taxReport({ invoices: allInvoices(), notes, currency, month }),
    aging(currency, asOf, termsDays) {
      return agingReport({ invoices: allInvoices(), balanceOf, asOf, currency, termsDays });
    },
    dunning: (asOf, termsDays) => dunningQueue(allInvoices(), balanceOf, asOf, termsDays),
    customerSummary(customerId, currency) {
      return customerSummary({
        customerId,
        currency,
        invoices: allInvoices(),
        notes,
        settlements,
        account,
        balanceOf,
      });
    },
    monthlyRecurringRevenue: (currency) =>
      monthlyRecurringRevenue([...subscriptions.values()], currency),
    renewalForecast: (currency) => renewalForecast([...subscriptions.values()], currency),
    subscriberMovement: (month) => subscriberMovement([...subscriptions.values()], month),
    churn: (month) => monthlyChurnBps([...subscriptions.values()], month),
    subscribersByPlan: () => subscribersByPlan([...subscriptions.values()]),
    deferredRevenue: (currency, asOf) => deferredRevenue({ invoices: allInvoices(), currency, asOf }),
    revenueCsv: (currency) =>
      revenueCsv(revenueByMonth({ invoices: allInvoices(), notes, currency }), currency),
    journalCsv: () => journalCsv(journal()),
    refundsToPay: () => refundQueue(notes, refundsPaidOut),
    markRefundPaid(noteNumber) {
      refundsPaidOut.push(noteNumber);
    },
    journal,
    unbalancedJournalEntries: () => journal().filter((entry) => entryImbalance(entry) !== 0),
    trialBalance: () => trialBalance(journal()),
    snapshot: (takenOn) =>
      bookSnapshot({
        subscriptions: [...subscriptions.values()],
        invoices: allInvoices(),
        notes,
        settlements,
        takenOn,
      }),
    invoicesCsv: () => invoicesCsv(allInvoices()),
    creditNotesCsv: () => creditNotesCsv(notes),
  };
}

/** What support looks at for one customer in one currency. */

import { formatLongDate } from '../core/dates.mjs';
import { formatAmount, sumAmounts } from '../core/money.mjs';

/** The ledger entries with a running balance added. */
export function accountHistory(entries) {
  let running = 0;
  return entries.map((entry) => {
    running += entry.amount;
    return { ...entry, balance: running };
  });
}

export function renderAccountStatement(customerId, currency, entries) {
  const lines = [`Account credit for ${customerId} in ${currency}`, ''];
  for (const entry of accountHistory(entries)) {
    const when = entry.date ? formatLongDate(entry.date) : 'undated';
    const reference = entry.reference ? ` ${entry.reference}` : '';
    lines.push(
      `${when}${reference}: ${formatAmount(entry.amount, currency)}, ` +
        `balance ${formatAmount(entry.balance, currency)}`,
    );
  }
  if (entries.length === 0) lines.push('No activity.');
  return `${lines.join('\n')}\n`;
}

function belongsTo(customerId, currency) {
  return (entry) => entry.customerId === customerId && entry.currency === currency;
}

export function customerSummary({ customerId, currency, invoices, notes, settlements, account, balanceOf }) {
  const matches = belongsTo(customerId, currency);
  const theirInvoices = invoices.filter(matches);
  const theirNotes = notes.filter(matches);
  const theirSettlements = settlements.filter(matches);
  return {
    customerId,
    currency,
    invoiceCount: theirInvoices.length,
    invoiced: sumAmounts(theirInvoices.map((invoice) => invoice.total)),
    credited: sumAmounts(theirNotes.map((note) => note.total)),
    refunded: sumAmounts(theirNotes.map((note) => note.settlement?.refunded ?? 0)),
    received: sumAmounts(
      theirSettlements.filter((entry) => entry.kind === 'payment').map((entry) => entry.amount),
    ),
    writtenOff: sumAmounts(
      theirSettlements.filter((entry) => entry.kind === 'write-off').map((entry) => entry.amount),
    ),
    open: sumAmounts(theirInvoices.map(balanceOf)),
    accountCredit: account.balance(customerId, currency),
  };
}
/**
 * Exports: spreadsheets for the finance team, with amounts in decimal form, and a
 * JSON snapshot of the whole book for the nightly backup.
 */

function decimal(amount) {
  return (amount / 100).toFixed(2);
}

function quote(value) {
  const text = String(value ?? '');
  return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function toCsv(header, rows) {
  return `${[header, ...rows].map((row) => row.map(quote).join(',')).join('\n')}\n`;
}

export function invoicesCsv(invoices) {
  const header = ['number', 'customer', 'currency', 'issued', 'net', 'tax', 'total', 'due'];
  const rows = invoices.map((invoice) => [
    invoice.number,
    invoice.customerId,
    invoice.currency,
    invoice.issueDate,
    decimal(invoice.netTotal, invoice.currency),
    decimal(invoice.taxTotal, invoice.currency),
    decimal(invoice.total, invoice.currency),
    decimal(invoice.amountDue, invoice.currency),
  ]);
  return toCsv(header, rows);
}

export function creditNotesCsv(notes) {
  const header = ['number', 'invoice', 'currency', 'issued', 'net', 'tax', 'total'];
  const rows = notes.map((note) => [
    note.number,
    note.invoiceNumber,
    note.currency,
    note.date,
    decimal(note.netTotal, note.currency),
    decimal(note.taxTotal, note.currency),
    decimal(note.total, note.currency),
  ]);
  return toCsv(header, rows);
}

function plain(value) {
  return JSON.parse(JSON.stringify(value));
}

/**
 * Everything in the book as one JSON document, in a stable order, with plans and
 * coupons reduced to their codes so the file does not repeat the catalog.
 */
export function bookSnapshot({ subscriptions, invoices, notes, settlements, takenOn }) {
  const compactRecord = (record) => ({
    ...plain(record),
    plan: record.plan.code,
    coupon: record.coupon ? record.coupon.code : null,
    scheduled: record.scheduled
      ? {
          ...plain(record.scheduled),
          plan: record.scheduled.plan ? record.scheduled.plan.code : undefined,
        }
      : null,
  });
  const byKey = (key) => (a, b) => String(a[key]).localeCompare(String(b[key]));
  return JSON.stringify(
    {
      takenOn,
      subscriptions: subscriptions.map(compactRecord).sort(byKey('id')),
      invoices: plain(invoices).sort(byKey('number')),
      creditNotes: plain(notes).sort(byKey('number')),
      settlements: plain(settlements),
    },
    null,
    2,
  );
}

/** Monthly revenue for one currency. */
export function revenueCsv(rows, currency) {
  const header = ['month', 'currency', 'revenue'];
  const body = rows.map(({ month, amount }) => [month, currency, decimal(amount, currency)]);
  return toCsv(header, body);
}

/** The journal, one row per leg, for the accounting system's import. */
export function journalCsv(entries) {
  const header = ['date', 'reference', 'currency', 'account', 'debit', 'credit'];
  const body = [];
  for (const { date, reference, currency, legs } of entries) {
    for (const { account, amount } of legs) {
      const debit = amount > 0 ? decimal(amount, currency) : '';
      const credit = amount < 0 ? decimal(-amount, currency) : '';
      body.push([date, reference, currency, account, debit, credit]);
    }
  }
  return toCsv(header, body);
}

/** The instalment plans agreed with customers, for the collections team. */
export function instalmentsCsv(plan, currency) {
  const header = ['number', 'due', 'currency', 'amount'];
  const body = plan.map(({ number, due, amount }) => [number, due, currency, decimal(amount, currency)]);
  return toCsv(header, body);
}
/**
 * Looking ahead: recurring revenue from active subscriptions and what the next
 * renewals should bring in, both at the terms that will apply.
 */

import { seatCharge } from '../catalog/plans.mjs';
import { divideRounded, scaleRounded } from '../core/rounding.mjs';
import { periodAt } from '../schedule/periods.mjs';
import { couponFor } from '../subscriptions/renewal.mjs';

const BASIS_POINTS = 10_000;

function afterCoupon(record, amount, periodIndex) {
  const coupon = couponFor(record, periodIndex);
  if (!coupon) return amount;
  return amount - scaleRounded(amount, coupon.percentBps, BASIS_POINTS);
}

function termsAtRenewal(record) {
  const { scheduled } = record;
  return {
    plan: scheduled?.plan ?? record.plan,
    seats: scheduled?.seats ?? record.seats,
  };
}

/** Recurring revenue per month across active subscriptions in one currency. */
export function monthlyRecurringRevenue(records, currency) {
  let total = 0;
  for (const record of records) {
    if (record.status !== 'active' || record.currency !== currency) continue;
    const charge = seatCharge(record.plan, currency, record.seats);
    const net = afterCoupon(record, charge, record.period.index);
    total += divideRounded(net, record.intervalMonths);
  }
  return total;
}

/** The next renewal of each active subscription that is not set to cancel. */
export function renewalForecast(records, currency) {
  const rows = [];
  for (const record of records) {
    if (record.status !== 'active' || record.currency !== currency) continue;
    if (record.scheduled?.cancel) continue;
