export function deferredRevenue({ invoices, notes = [], currency, asOf }) {
  parseIsoDate(asOf);
  let total = 0;
  for (const invoice of invoices) {
    if (invoice.currency !== currency) continue;
    const credited = creditedToDate(
      invoice,
      notes.filter((note) => note.invoiceNumber === invoice.number),
    );
    invoice.lines.forEach((line, index) => {
      if (!line.period || line.net === 0) return;
      // Credit notes already gave back part of what the line charged.
      const remaining = line.net > 0 ? line.net - credited[index].net : line.net;
      total += deferredPart({ ...line, net: remaining }, asOf);
    });
  }
  return total;
}

