import assert from 'node:assert/strict';
import { test } from 'node:test';

import {
  allocate,
  billingPeriods,
  buildInvoice,
  definePlan,
  formatAmount,
  parseAmount,
  planChangeAmounts,
  settleCreditNote,
  periodAt,
} from '../src/index.mjs';
import { makeBook, subscribeTo } from './support/world.mjs';

const sum = (values) => values.reduce((total, value) => total + value, 0);

test('amounts use the currency decimals', () => {
  assert.equal(parseAmount('2900', 'JPY'), 2900);
  assert.equal(parseAmount('1.234', 'KWD'), 1234);
  assert.equal(formatAmount(2900, 'JPY'), 'JPY 2,900');
  assert.equal(formatAmount(-1234, 'KWD'), 'KWD -1.234');
  assert.equal(formatAmount(5, 'KWD'), 'KWD 0.005');
  assert.throws(() => parseAmount('10.5', 'JPY'), RangeError);
  assert.equal(definePlan({ code: 'k', prices: { KWD: '3.500' } }).prices.KWD, 3500);
});

test('renewals keep the anchor day after a short month', () => {
  const ends = billingPeriods('2024-01-31', 1, 4).map((period) => period.end);
  assert.deepEqual(ends, ['2024-02-29', '2024-03-31', '2024-04-30', '2024-05-31']);
  assert.equal(periodAt('2023-01-31', 1, 2).start, '2023-03-31');
  assert.equal(periodAt('2023-01-31', 3, 1).end, '2023-07-31');
});

test('proration counts the change day as time left', () => {
  const period = { start: '2024-02-01', end: '2024-03-01' };
  const result = planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-16' });
  assert.deepEqual(result, { credit: -1400, charge: 2800, net: 1400 });
});

test('allocate is fair and mirrors for negatives', () => {
  assert.deepEqual(allocate(10, [1, 1, 1]), [4, 3, 3]);
  assert.deepEqual(allocate(-10, [1, 1, 1]), [-4, -3, -3]);
  assert.deepEqual(allocate(5, [0, 1, 0]), [0, 5, 0]);
  assert.deepEqual(allocate(1, [1, 0, 1, 1]), [1, 0, 0, 0]);
});

test('invoice lines add up to the totals and per-rate tax', () => {
  const lines = [1, 2, 3, 4, 5].map((n) => ({ description: `l${n}`, unitAmount: 333 * n + 1, taxRateBps: 1900 }));
  const invoice = buildInvoice({ number: 'X', customerId: 'c', currency: 'EUR', issueDate: '2024-01-01', lines });
  assert.equal(sum(invoice.lines.map((line) => line.tax)), invoice.taxTotal);
  assert.equal(sum(invoice.lines.map((line) => line.gross)), invoice.total);
  for (const line of invoice.lines) assert.ok(Math.abs(line.tax - (line.net * 1900) / 10000) <= 1);
});

test('account credit settles an invoice without changing its tax', () => {
  const input = {
    number: 'X',
    customerId: 'c',
    currency: 'EUR',
    issueDate: '2024-01-01',
    lines: [{ description: 'a', unitAmount: 1000, taxRateBps: 2000 }],
  };
  const plain = buildInvoice(input);
  const credited = buildInvoice({ ...input, accountCredit: 500 });
  assert.equal(credited.taxTotal, plain.taxTotal);
  assert.equal(credited.total, plain.total);
  assert.equal(credited.amountDue, plain.total - 500);
});

test('staged credit notes end on the full tax and a zero balance', () => {
  const book = makeBook();
  const invoice = subscribeTo(book, { currency: 'EUR' });
  book.pay(invoice.number, { amount: invoice.amountDue, date: '2024-04-02' });
  for (const amount of [1001, 1003, 1007]) {
    book.creditInvoice(invoice.number, { date: '2024-04-05', lines: [{ lineIndex: 0, amount }] });
  }
  book.creditInvoice(invoice.number, { date: '2024-04-06' });
  const notes = book.notesOn(invoice.number);
  assert.equal(sum(notes.map((note) => note.taxTotal)), invoice.taxTotal);
  assert.equal(sum(notes.map((note) => note.netTotal)), invoice.netTotal);
  assert.equal(book.balanceOf(invoice.number), 0);
  assert.throws(() => book.creditInvoice(invoice.number, { date: '2024-04-07', lines: [{ lineIndex: 0, amount: 1 }] }));
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});

test('credit beyond the cash received goes to the account', () => {
  assert.deepEqual(settleCreditNote(1000, { openBalance: 200, cashAvailable: 500 }), {
    againstBalance: 200,
    refunded: 500,
    toAccount: 300,
  });
});

test('a discounted change never gives back more than was paid', () => {
  const book = makeBook();
  const first = subscribeTo(book, { couponCode: 'WELCOME', anchor: '2024-04-01' });
  const change = book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  const credit = change.lines.find((line) => line.reverses);
  assert.ok(-credit.net <= first.lines[0].net);
  // The discount still covers the new charge, and the change did not use a period.
  assert.ok(change.lines.at(-1).discount > 0);
  const renewal = book.renew('sub_1');
  assert.ok(renewal.lines[0].discount > 0);
  assert.equal(book.renew('sub_1').lines[0].discount, 0);
});

test('a change keeps what is scheduled for the next renewal', () => {
  const book = makeBook();
  subscribeTo(book);
  book.scheduleForRenewal('sub_1', { planCode: 'business' });
  book.changePlan('sub_1', { date: '2024-04-10', seats: 2 });
  assert.equal(book.subscription('sub_1').scheduled.plan.code, 'business');
});

test('invoice numbers never skip when a request fails', () => {
  const book = makeBook();
  subscribeTo(book);
  assert.throws(() => book.changePlan('sub_1', { date: '2030-01-01', planCode: 'business' }));
  assert.equal(book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' }).number, 'INV-0002');
});

test('paying part from account credit leaves the books balanced', () => {
  const book = makeBook();
  book.grantAccountCredit('cus_1', 'USD', { amount: 700, date: '2024-04-01' });
  const invoice = subscribeTo(book);
  assert.equal(invoice.creditApplied, 700);
  assert.equal(book.balanceOf(invoice.number), invoice.total - 700);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});
